package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)
var WsGross decimal.Decimal = decimal.NewFromInt(0)
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecVar EmpRec

var empFile *os.File
var empScanner *bufio.Scanner
var inputDone bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func isFirstRecord() bool {
	return WsFirstFlag == "Y"
}

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func formatNumericEdited(value decimal.Decimal, picture string) string {
	// Determine scale from picture
	dotIdx := strings.Index(picture, ".")
	scale := 0
	if dotIdx >= 0 {
		scale = len(picture) - dotIdx - 1
	}
	// Truncate to scale (COBOL store truncation when moving to edited? Actually edited field reflects value as is)
	// But we ensure value is already at correct scale
	// Format to string with scale decimals
	shifted := value.Shift(int32(scale))
	// shifted should be integer (truncate already)
	// Use string representation
	s := shifted.String()
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	// s is integer digits of value*10^scale
	// Pad with leading zeros to ensure at least scale+1 digits
	if len(s) <= scale {
		s = strings.Repeat("0", scale+1-len(s)) + s
	}
	var intPart, fracPart string
	if scale > 0 {
		intPart = s[:len(s)-scale]
		fracPart = s[len(s)-scale:]
	} else {
		intPart = s
		fracPart = ""
	}
	// intPart may have leading zeros; keep as is for overflow handling

	// Build picture structure for integer part and fractional part
	var picInt, picFrac string
	if dotIdx >= 0 {
		picInt = picture[:dotIdx]
		picFrac = picture[dotIdx+1:]
	} else {
		picInt = picture
		picFrac = ""
	}

	// Overflow handling: if intPart has more digits than number of digit positions in picInt, drop high-order digits
	digitCountPicInt := 0
	for _, c := range picInt {
		if c == '9' || c == 'Z' {
			digitCountPicInt++
		}
	}
	if len(intPart) > digitCountPicInt {
		intPart = intPart[len(intPart)-digitCountPicInt:]
	}
	// Left pad intPart with zeros to match digitCountPicInt
	if len(intPart) < digitCountPicInt {
		intPart = strings.Repeat("0", digitCountPicInt-len(intPart)) + intPart
	}

	// Now map intPart digits to picture positions
	// picInt may contain commas
	// We need to produce formatted string same length as picture
	// For Z suppression: leading zeros become spaces, commas inside suppressed zone become spaces
	resultInt := make([]byte, len(picInt))
	digitIdx := 0
	// intPart is exactly digitCountPicInt chars
	for i := 0; i < len(picInt); i++ {
		c := picInt[i]
		if c == '9' || c == 'Z' {
			resultInt[i] = intPart[digitIdx]
			digitIdx++
		} else if c == ',' {
			resultInt[i] = ','
		} else {
			resultInt[i] = byte(c)
		}
	}
	// Apply Z suppression
	suppressing := true
	for i := 0; i < len(picInt); i++ {
		c := picInt[i]
		if c == 'Z' {
			if suppressing {
				if resultInt[i] == '0' {
					resultInt[i] = ' '
				} else {
					suppressing = false
				}
			} else {
				// no longer suppressing
			}
		} else if c == '9' {
			suppressing = false
		} else if c == ',' {
			if suppressing {
				// check if any non-suppressed digit follows? In COBOL, commas in suppressed zone become spaces
				// Our suppressing flag indicates we are still in leading zero zone
				// So comma becomes space while suppressing
				resultInt[i] = ' '
			} else {
				// keep comma
			}
		}
	}
	// After suppression, if all integer digits were suppressed, the spaces remain; that's correct

	// Fractional part: picture frac is 9's only typically; just map digits
	resultFrac := ""
	if scale > 0 {
		// picFrac length == scale
		// fracPart already scale digits
		if len(fracPart) < len(picFrac) {
			fracPart = fracPart + strings.Repeat("0", len(picFrac)-len(fracPart))
		} else if len(fracPart) > len(picFrac) {
			fracPart = fracPart[:len(picFrac)]
		}
		resultFrac = fracPart
	}

	var out string
	if dotIdx >= 0 {
		out = string(resultInt) + "." + resultFrac
	} else {
		out = string(resultInt)
	}
	if neg {
		// COBOL would show sign; not needed for this program
		out = "-" + out
	}
	return out
}

func moveToHoursEd(v decimal.Decimal) {
	// PIC ZZ9.9 -> scale 1, width 5
	v = truncateDecimal(v, 1)
	WsHoursEd = formatNumericEdited(v, "ZZ9.9")
}
func moveToRateEd(v decimal.Decimal) {
	v = truncateDecimal(v, 2)
	WsRateEd = formatNumericEdited(v, "ZZ9.99")
}
func moveToGrossEd(v decimal.Decimal) {
	v = truncateDecimal(v, 2)
	WsGrossEd = formatNumericEdited(v, "Z,ZZZ,ZZ9.99")
}
func moveToDeptEd(v decimal.Decimal) {
	v = truncateDecimal(v, 2)
	WsDeptEd = formatNumericEdited(v, "ZZZ,ZZZ,ZZ9.99")
}
func moveToGrandEd(v decimal.Decimal) {
	v = truncateDecimal(v, 2)
	WsGrandEd = formatNumericEdited(v, "ZZ,ZZZ,ZZZ,ZZ9.99")
}

func parseInputLine(line string) EmpRec {
	// Pad to 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	}
	if len(line) > 17 {
		line = line[:17]
	}
	erId := line[0:5]
	erDept := line[5:8]
	erHoursRaw := line[8:12]
	erRateRaw := line[12:17]
	erHours := parseDecimalDigits(erHoursRaw, 1)
	erRate := parseDecimalDigits(erRateRaw, 2)
	return EmpRec{ErId: erId, ErDept: erDept, ErHours: erHours, ErRate: erRate}
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// digits only
	d := decimal.RequireFromString(s)
	return d.Shift(-scale)
}

func storeWsGross(v decimal.Decimal) {
	// PIC 9(7)V99: 7 int +2 dec = keep low-order digits fitting 9 digits total
	// Implement truncation to 2 decimals then overflow drop high-order
	v = truncateDecimal(v, 2)
	WsGross = keepLowOrderDigits(v, 7, 2)
}
func keepLowOrderDigits(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Keep truncation already done
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	shifted := v.Shift(scale) // integer value
	s := shifted.String()
	// s is like "12345"
	// Total digits allowed = intDigits + scale
	totalAllowed := intDigits + int(scale)
	if len(s) > totalAllowed {
		s = s[len(s)-totalAllowed:]
	}
	d := decimal.RequireFromString(s)
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func main() {
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// If file not exists, treat as empty
		empFile = nil
		empScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		defer empFile.Close()
		empScanner = bufio.NewScanner(empFile)
		// COBOL LINE SEQUENTIAL: allow long lines
		buf := make([]byte, 0, 64*1024)
		empScanner.Buffer(buf, 10*1024*1024)
	}

	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT EMP-FILE
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		DEPT_BREAK_PARA()
	}
	// CLOSE
	GRAND_PARA()
}

func READ_PARA() {
	if empScanner.Scan() {
		line := empScanner.Text()
		// Remove trailing \r if any
		line = strings.TrimSuffix(line, "\r")
		EmpRecVar = parseInputLine(line)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	forty := decimal.NewFromInt(40)
	if EmpRecVar.ErHours.GreaterThan(forty) {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = EmpRecVar.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = truncateDecimal(WsOtHours, 1)
	} else {
		WsRegHours = truncateDecimal(EmpRecVar.ErHours, 1)
		WsOtHours = decimal.NewFromInt(0)
	}
	// COMPUTE WS-GROSS ROUNDED = ...
	onePointFive := decimal.NewFromInt(15).Shift(-1) // 1.5
	grossUnrounded := WsRegHours.Mul(EmpRecVar.ErRate).Add(WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive))
	rounded := grossUnrounded.Round(2)
	storeWsGross(rounded)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptCount = WsDeptCount + 1
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandCount = WsGrandCount + 1

	moveToHoursEd(EmpRecVar.ErHours)
	moveToRateEd(EmpRecVar.ErRate)
	moveToGrossEd(WsGross)

	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED.
	fmt.Printf("%s %s %s %s %s\n", EmpRecVar.ErId, EmpRecVar.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPT_BREAK_PARA() {
	moveToDeptEd(WsDeptTotal)
	// DISPLAY "  DEPT " WS-PREV-DEPT " EMPLOYEES: " WS-DEPT-COUNT " TOTAL: " WS-DEPT-ED
	WsDeptCountStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, WsDeptCountStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GRAND_PARA() {
	moveToGrandEd(WsGrandTotal)
	WsGrandCountStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", WsGrandCountStr, WsGrandEd)
}
